const deleteAbandonedUnverifiedSignupUsers = `-- name: DeleteAbandonedUnverifiedSignupUsers :execrows
WITH candidates AS MATERIALIZED (
    SELECT users.id
    FROM users
    WHERE users.created_at < transaction_timestamp() - ($1::bigint * interval '1 second')
      AND EXISTS (
          SELECT 1
          FROM user_emails email
          WHERE email.user_id = users.id
            AND email.verified_at IS NULL
      )
      AND NOT EXISTS (
          SELECT 1
          FROM user_emails email
          WHERE email.user_id = users.id
            AND email.verified_at IS NOT NULL
      )
      AND NOT EXISTS (
          SELECT 1
          FROM user_auth_tokens token
          WHERE token.user_id = users.id
            AND token.consumed_at IS NULL
            AND token.expires_at > transaction_timestamp()
      )
      AND NOT EXISTS (
          SELECT 1
          FROM user_credentials credential
          WHERE credential.user_id = users.id
      )
      AND NOT EXISTS (
          SELECT 1
          FROM user_auth_identities identity
          WHERE identity.user_id = users.id
      )
      AND NOT EXISTS (
          SELECT 1
          FROM personal_access_tokens token
          WHERE token.user_id = users.id
      )
      AND NOT EXISTS (
          SELECT 1
          FROM browser_sessions session
          WHERE session.user_id = users.id
      )
      AND NOT EXISTS (
          SELECT 1
          FROM org_memberships membership
          WHERE membership.user_id = users.id
      )
    ORDER BY users.created_at, users.id
    LIMIT $2
),
deleted_tokens AS (
    DELETE FROM user_auth_tokens token
    USING candidates
    WHERE token.user_id = candidates.id
    RETURNING token.id
),
deleted_emails AS (
    DELETE FROM user_emails email
    USING candidates
    WHERE email.user_id = candidates.id
      AND email.verified_at IS NULL
    RETURNING email.id
)
DELETE FROM users
USING candidates
WHERE users.id = candidates.id
`

type DeleteAbandonedUnverifiedSignupUsersParams struct {
	MinimumAgeSeconds int64
	LimitCount        int32
}

// @sqlc-vet-disable users-deleted-at
// Hard-delete purge: abandonment criteria are independent of soft deletion.
func (q *Queries) DeleteAbandonedUnverifiedSignupUsers(ctx context.Context, arg DeleteAbandonedUnverifiedSignupUsersParams) (int64, error) {
	result, err := q.db.Exec(ctx, deleteAbandonedUnverifiedSignupUsers, arg.MinimumAgeSeconds, arg.LimitCount)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

