const listOrgMembers = `-- name: ListOrgMembers :many
WITH listed AS (
 SELECT u.id AS user_id, u.display_name, om.role, om.created_at,
        CASE $6::text
          WHEN 'name' THEN lower(u.display_name)
          WHEN 'created_at' THEN to_char(om.created_at AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.US')
        END::text AS sort_key,
        false AS sort_is_null
 FROM org_memberships om
 JOIN users u ON u.id = om.user_id
 WHERE om.org_id = $7
   AND u.deleted_at IS NULL
   AND ($8::text = '' OR u.display_name ILIKE $8::text ESCAPE '\')
)
SELECT user_id, display_name, role, created_at, sort_key, sort_is_null
FROM listed
WHERE $1::boolean = false
   OR ($2::boolean = false AND (sort_key, user_id) > ($3::text, $4::uuid))
   OR ($2::boolean = true AND (sort_key, user_id) < ($3::text, $4::uuid))
ORDER BY CASE WHEN NOT $2::boolean THEN sort_key END ASC,
         CASE WHEN $2::boolean THEN sort_key END DESC,
         CASE WHEN NOT $2::boolean THEN user_id END ASC,
         CASE WHEN $2::boolean THEN user_id END DESC
LIMIT $5::bigint
`

