const primaryVerifiedEmailsForUsers = `-- name: PrimaryVerifiedEmailsForUsers :many
SELECT user_id, email
FROM user_emails
WHERE user_id = ANY($1::uuid[])
  AND verified_at IS NOT NULL
  AND is_primary
`

type PrimaryVerifiedEmailsForUsersParams struct {
	UserIds []uuid.UUID
}

type PrimaryVerifiedEmailsForUsersRow struct {
	UserID uuid.UUID
	Email  string
}

func (q *Queries) PrimaryVerifiedEmailsForUsers(ctx context.Context, arg PrimaryVerifiedEmailsForUsersParams) ([]PrimaryVerifiedEmailsForUsersRow, error) {
	rows, err := q.db.Query(ctx, primaryVerifiedEmailsForUsers, arg.UserIds)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []PrimaryVerifiedEmailsForUsersRow{}
	for rows.Next() {
		var i PrimaryVerifiedEmailsForUsersRow
		if err := rows.Scan(&i.UserID, &i.Email); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

