const userIsLastOwnerOfAnyOrg = `-- name: UserIsLastOwnerOfAnyOrg :one
SELECT EXISTS (
  SELECT 1 FROM org_memberships membership
  JOIN orgs org ON org.id = membership.org_id AND org.deleted_at IS NULL
  WHERE membership.user_id = $1::uuid
    AND membership.role = 'owner'
    AND NOT EXISTS (
      SELECT 1 FROM org_memberships other
      WHERE other.org_id = membership.org_id
        AND other.role = 'owner'
        AND other.user_id IS NOT NULL
        AND other.user_id <> membership.user_id
    )
) AS is_last_owner
`

type UserIsLastOwnerOfAnyOrgParams struct {
	UserID uuid.UUID
}

func (q *Queries) UserIsLastOwnerOfAnyOrg(ctx context.Context, arg UserIsLastOwnerOfAnyOrgParams) (bool, error) {
	row := q.db.QueryRow(ctx, userIsLastOwnerOfAnyOrg, arg.UserID)
	var is_last_owner bool
	err := row.Scan(&is_last_owner)
	return is_last_owner, err
}

